package com.hamiltel.gmlc.consistency;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Turns the committed OpenAPI schemas into {@code console/src/types.ts}.
 *
 * <p>Optionality comes only from each schema's {@code required} list, so the
 * console cannot assume a field the server may omit. The generated file is
 * checked in and regenerated by {@link TypesDriftTest} when
 * {@code -Dgmlc.write.types=true} is passed.
 */
final class TypeScriptGenerator {

    private TypeScriptGenerator() {
    }

    @SuppressWarnings("unchecked")
    static String render(Map<String, Object> spec) {
        Map<String, Object> components = (Map<String, Object>) spec.get("components");
        Map<String, Object> schemas = (Map<String, Object>) components.get("schemas");

        StringBuilder out = new StringBuilder();
        out.append("// GENERATED FILE - do not edit.\n");
        out.append("// Source: api/openapi.yaml, components.schemas.\n");
        out.append("// Regenerate: mvn -o -B -pl gmlc-app test -Dtest=TypesDriftTest ")
                .append("-Dgmlc.write.types=true\n\n");

        for (Map.Entry<String, Object> entry : schemas.entrySet()) {
            String name = entry.getKey();
            Map<String, Object> schema = (Map<String, Object>) entry.getValue();
            if (schema.get("enum") instanceof List<?> values) {
                out.append("export type ").append(name).append(" = ")
                        .append(literals(values)).append(";\n\n");
                continue;
            }
            Object allOf = schema.get("allOf");
            if (allOf instanceof List<?> parts) {
                List<String> types = new ArrayList<>();
                for (Object part : parts) {
                    types.add(typeOf((Map<String, Object>) part));
                }
                out.append("export type ").append(name).append(" = ")
                        .append(String.join(" & ", types)).append(";\n\n");
                continue;
            }
            Object properties = schema.get("properties");
            if (properties instanceof Map<?, ?> props) {
                out.append("export interface ").append(name).append(" {\n");
                Set<String> required = required(schema);
                for (Map.Entry<?, ?> property : props.entrySet()) {
                    String key = property.getKey().toString();
                    String optional = required.contains(key) ? "" : "?";
                    out.append("  ").append(key).append(optional).append(": ")
                            .append(typeOf((Map<String, Object>) property.getValue()))
                            .append(";\n");
                }
                out.append("}\n\n");
                continue;
            }
            out.append("export type ").append(name).append(" = ")
                    .append(typeOf(schema)).append(";\n\n");
        }
        return out.toString().stripTrailing() + "\n";
    }

    @SuppressWarnings("unchecked")
    private static String typeOf(Map<String, Object> schema) {
        Object ref = schema.get("$ref");
        if (ref != null) {
            String value = ref.toString();
            return value.substring(value.lastIndexOf('/') + 1);
        }
        if (schema.get("enum") instanceof List<?> values) {
            return literals(values);
        }
        Object allOf = schema.get("allOf");
        if (allOf instanceof List<?> parts) {
            List<String> types = new ArrayList<>();
            for (Object part : parts) {
                types.add(typeOf((Map<String, Object>) part));
            }
            return String.join(" & ", types);
        }
        Object type = schema.get("type");
        if (type instanceof List<?> union) {
            List<String> types = new ArrayList<>();
            for (Object alternative : union) {
                types.add(primitive(alternative.toString()));
            }
            return String.join(" | ", types);
        }
        if (type == null) {
            Object properties = schema.get("properties");
            if (properties instanceof Map<?, ?> props && !props.isEmpty()) {
                return inline(props, required(schema));
            }
            Object additional = schema.get("additionalProperties");
            if (additional instanceof Map<?, ?> valueSchema) {
                return "Record<string, " + typeOf((Map<String, Object>) valueSchema) + ">";
            }
            if (Boolean.TRUE.equals(additional)) {
                return "Record<string, unknown>";
            }
            if (schema.containsKey("additionalProperties") || schema.isEmpty()) {
                return "unknown";
            }
            return "unknown";
        }
        switch (type.toString()) {
            case "array":
                Object items = schema.get("items");
                String item = items instanceof Map<?, ?>
                        ? typeOf((Map<String, Object>) items) : "unknown";
                if (item.contains(" | ") || item.contains(" & ")) {
                    return "(" + item + ")[]";
                }
                return item + "[]";
            case "object":
                Object properties = schema.get("properties");
                if (properties instanceof Map<?, ?> props && !props.isEmpty()) {
                    return inline(props, required(schema));
                }
                Object additional = schema.get("additionalProperties");
                if (additional instanceof Map<?, ?> valueSchema) {
                    return "Record<string, " + typeOf((Map<String, Object>) valueSchema) + ">";
                }
                return "Record<string, unknown>";
            default:
                return primitive(type.toString());
        }
    }

    private static String primitive(String type) {
        return switch (type) {
            case "string" -> "string";
            case "integer", "number" -> "number";
            case "boolean" -> "boolean";
            case "null" -> "null";
            default -> "unknown";
        };
    }

    @SuppressWarnings("unchecked")
    private static String inline(Map<?, ?> properties, Set<String> required) {
        List<String> fields = new ArrayList<>();
        for (Map.Entry<?, ?> property : properties.entrySet()) {
            String key = property.getKey().toString();
            String optional = required.contains(key) ? "" : "?";
            fields.add(key + optional + ": "
                    + typeOf((Map<String, Object>) property.getValue()));
        }
        return fields.isEmpty() ? "Record<string, unknown>" : "{ " + String.join("; ", fields) + " }";
    }

    @SuppressWarnings("unchecked")
    private static Set<String> required(Map<String, Object> schema) {
        Set<String> names = new LinkedHashSet<>();
        Object required = schema.get("required");
        if (required instanceof List<?> values) {
            for (Object value : values) {
                names.add(value.toString());
            }
        }
        Object allOf = schema.get("allOf");
        if (allOf instanceof List<?> parts) {
            for (Object part : parts) {
                names.addAll(required((Map<String, Object>) part));
            }
        }
        return names;
    }

    private static String literals(List<?> values) {
        List<String> literals = new ArrayList<>();
        for (Object value : values) {
            if (value instanceof Number || value instanceof Boolean) {
                literals.add(value.toString());
            } else {
                literals.add("'" + value.toString().replace("\\", "\\\\").replace("'", "\\'") + "'");
            }
        }
        return literals.isEmpty() ? "never" : String.join(" | ", literals);
    }
}
